insert into public.labor_rules (id, jurisdiction, topic, answer, plain_english, legal_basis, source_url, last_verified_at, valid_through, reviewed_by, status)
values
  ('us-meal_break', 'US', 'meal_break', 'no', 'Federal law doesn''t require meal breaks. If your employer gives you one of about 30 minutes or more and you''re completely relieved of duty, it can be unpaid. Your state may require one.', 'Fair Labor Standards Act; 29 CFR 785.19 (meal periods)', 'https://www.dol.gov/general/topic/workhours/breaks', '2026-10-27', null, 'pending attorney review', 'published'),
  ('us-rest_break', 'US', 'rest_break', 'no', 'Federal law doesn''t require rest or coffee breaks. If your employer gives short breaks, they must be paid. Your state may require breaks.', 'Fair Labor Standards Act; 29 CFR 785.18 (rest periods)', 'https://www.dol.gov/general/topic/workhours/breaks', '2026-10-27', null, 'pending attorney review', 'published'),
  ('us-break_pay', 'US', 'break_pay', 'yes', 'Short breaks of about 5 to 20 minutes count as paid work time. A meal period of about 30 minutes or more can be unpaid, but only if you''re completely relieved of duty. If you have to keep working while you eat, that time is paid.', 'Fair Labor Standards Act; 29 CFR 785.18 and 785.19', 'https://www.dol.gov/general/topic/workhours/breaks', '2026-10-27', null, 'pending attorney review', 'published'),
  ('us-tip_credit', 'US', 'tip_credit', 'yes', 'Under federal law your employer can pay as little as $2.13 an hour in cash wages and count up to $5.12 an hour of your tips toward the $7.25 minimum wage. If your tips don''t make up the difference, your employer must. They have to tell you about the tip credit before using it. Many states set higher wages.', 'Fair Labor Standards Act, 29 U.S.C. 203(m); DOL Fact Sheet #15', 'https://www.dol.gov/agencies/whd/fact-sheets/15-tipped-employees-flsa', '2026-10-27', null, 'pending attorney review', 'published'),
  ('us-manager_tips', 'US', 'manager_tips', 'no', 'Your employer can''t keep any part of your tips for any purpose, and can''t make you give tips to a manager or supervisor, including through a tip pool.', 'Fair Labor Standards Act, 29 U.S.C. 203(m)(2)(B); DOL Fact Sheet #15', 'https://www.dol.gov/agencies/whd/fact-sheets/15-tipped-employees-flsa', '2026-10-27', null, 'pending attorney review', 'published'),
  ('us-tip_pool', 'US', 'tip_pool', 'depends', 'Often yes, with limits. If your employer pays you a tipped wage (takes a tip credit), a required tip pool can include only workers who customarily and regularly get tips, like servers, bussers and bartenders. If you''re paid at least the full $7.25 minimum wage in cash, the pool can also include workers like cooks and dishwashers. Managers and supervisors can never be in it.', 'Fair Labor Standards Act, 29 U.S.C. 203(m); DOL Fact Sheet #15', 'https://www.dol.gov/agencies/whd/fact-sheets/15-tipped-employees-flsa', '2026-10-27', null, 'pending attorney review', 'published'),
  ('us-card_fees', 'US', 'card_fees', 'depends', 'Under federal law, your employer may take out only the card company''s percentage fee from a tip paid by card, and no more than that fee. Some states don''t allow even that.', 'Fair Labor Standards Act, 29 U.S.C. 203(m); DOL Fact Sheet #15', 'https://www.dol.gov/agencies/whd/fact-sheets/15-tipped-employees-flsa', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ca-meal_break', 'CA', 'meal_break', 'yes', 'Yes, on shifts of more than 5 hours you''re owed a 30-minute meal period. If the shift is 6 hours or less, you and your employer can agree to skip it. Over 10 hours, you''re owed a second one. If you don''t get a required meal period, you''re owed one extra hour of pay at your regular rate for that day.', 'California Labor Code section 512; Industrial Welfare Commission Wage Orders', 'https://www.dir.ca.gov/dlse/faq_mealperiods.htm', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ca-rest_break', 'CA', 'rest_break', 'yes', 'Yes. You''re owed a paid 10-minute rest break for every 4 hours you work, or major fraction of 4 hours. It isn''t required if you work less than 3½ hours that day. If you don''t get a required rest break, you''re owed one extra hour of pay at your regular rate for that day.', 'Industrial Welfare Commission Wage Orders', 'https://www.dir.ca.gov/dlse/faq_restperiods.htm', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ca-break_pay', 'CA', 'break_pay', 'yes', 'Rest breaks are paid. A meal period can be unpaid only if you''re relieved of all duty for the full 30 minutes. If you''re kept on duty, it counts as time worked and must be paid.', 'California Labor Code section 512; Industrial Welfare Commission Wage Orders', 'https://www.dir.ca.gov/dlse/faq_mealperiods.htm', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ca-tip_credit', 'CA', 'tip_credit', 'no', 'No. California doesn''t allow a tip credit. You must get at least the full state minimum wage, $16.90 an hour in 2026, plus all your tips. Many cities and counties set a higher minimum wage.', 'California Labor Code section 351; California minimum wage law', 'https://www.dir.ca.gov/dlse/faq_minimumwage.htm', '2026-10-27', '2026-12-31', 'pending attorney review', 'published'),
  ('ca-manager_tips', 'CA', 'manager_tips', 'no', 'No. Your employer can''t take any part of your tips, can''t deduct money from your wages because of your tips, and can''t count your tips against what it owes you. Owners, managers and supervisors can''t share in a tip pool, even if they serve tables.', 'California Labor Code section 351', 'https://www.dir.ca.gov/dlse/faq_tipsandgratuities.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ca-tip_pool', 'CA', 'tip_pool', 'depends', 'Usually yes. Your employer can require you to share tips with other staff who serve guests, like bussers and bartenders, if the policy is fair and reasonable and only goes to employees in the chain of service. Owners, managers and supervisors can''t be included.', 'California Labor Code section 351', 'https://www.dir.ca.gov/dlse/faq_tipsandgratuities.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ca-card_fees', 'CA', 'card_fees', 'no', 'No. Your employer must pay you the full tip written on the card slip, with nothing taken out for card processing fees, no later than the next regular payday.', 'California Labor Code section 351', 'https://www.dir.ca.gov/dlse/faq_tipsandgratuities.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('tx-meal_break', 'TX', 'meal_break', 'no', 'No. Neither Texas law nor federal law requires meal breaks. If you get a meal break of at least 30 minutes and you''re completely relieved of duty, it can be unpaid. Some Texas cities have their own break rules.', 'No Texas statute; Fair Labor Standards Act', 'https://efte.twc.texas.gov/d_breaks.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('tx-rest_break', 'TX', 'rest_break', 'no', 'No. Neither Texas law nor federal law requires rest breaks. If your employer gives breaks of 20 minutes or less, they must be paid. Some Texas cities have their own break rules.', 'No Texas statute; Fair Labor Standards Act', 'https://efte.twc.texas.gov/d_breaks.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('tx-break_pay', 'TX', 'break_pay', 'yes', 'Rest or coffee breaks of 20 minutes or less are paid work time. Meal breaks of at least 30 minutes can be unpaid if you''re completely relieved of duty; if you have to work while eating, that time is paid.', 'Fair Labor Standards Act (applies in Texas)', 'https://efte.twc.texas.gov/d_breaks.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('tx-tip_credit', 'TX', 'tip_credit', 'yes', 'Yes. Texas uses the federal minimum wage of $7.25. Your employer can pay a cash wage of $2.13 an hour and count up to $5.12 an hour of your tips, as long as your tips make up the difference and they told you about the tip credit first.', 'Fair Labor Standards Act, 29 U.S.C. 203(m); Texas Minimum Wage Act (Texas Labor Code chapter 62)', 'https://www.dol.gov/agencies/whd/state/minimum-wage/tipped', '2026-10-27', null, 'pending attorney review', 'published'),
  ('tx-manager_tips', 'TX', 'manager_tips', 'no', 'No. Owners and managers can''t keep employee tips. A required tip pool can include only employees who customarily and regularly get tips.', 'Fair Labor Standards Act, 29 U.S.C. 203(m)', 'https://efte.twc.texas.gov/tip_pooling.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ny-meal_break', 'NY', 'meal_break', 'depends', 'It depends on when you work. A shift of more than 6 hours that covers 11 a.m. to 2 p.m. gets at least 30 minutes off in that window. A shift of more than 6 hours that starts between 1 p.m. and 6 a.m. gets 45 minutes, midway through. If you start before 11 a.m. and work past 7 p.m., you get another 20 minutes between 5 and 7 p.m.', 'New York Labor Law section 162', 'https://www.nysenate.gov/legislation/laws/LAB/162', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ny-rest_break', 'NY', 'rest_break', 'no', 'No. New York doesn''t require paid rest breaks for adults. Meal periods are a separate rule.', 'No New York statute requiring paid rest periods (US DOL table of state rest period laws)', 'https://www.dol.gov/agencies/whd/state/rest-periods', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ny-tip_credit', 'NY', 'tip_credit', 'yes', 'Yes, for food service workers like servers and bartenders. In 2026 the cash wage is at least $11.35 an hour in New York City, Long Island and Westchester (up to $5.65 of tips counted toward the $17.00 minimum), and at least $10.70 in the rest of the state (up to $5.30 toward $16.00). Your employer can''t take the tip credit on a day you spend more than 2 hours, or 20% of your shift, on non-tipped work, whichever is less.', 'New York Minimum Wage Act; Hospitality Industry Wage Order (12 NYCRR Part 146)', 'https://dol.ny.gov/minimum-wage-tipped-workers-p717-english', '2026-10-27', '2026-12-31', 'pending attorney review', 'published'),
  ('ny-manager_tips', 'NY', 'manager_tips', 'no', 'No. Your employer, or anyone acting for them like a manager, can''t demand, accept or keep any part of a tip left for you, or any charge presented to guests as a tip.', 'New York Labor Law section 196-d', 'https://dol.ny.gov/system/files/documents/2025/01/tips-and-gratuities-frequently-asked-questions.pdf', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ny-tip_pool', 'NY', 'tip_pool', 'depends', 'Yes, within limits. Your employer can require you to share or pool tips with other food service workers who served the guests, like bussers and bartenders, and can set the percentages. Your employer must keep records of what the pool collects and pays out, and can''t take any part of it.', 'Hospitality Industry Wage Order (12 NYCRR Part 146); New York Labor Law section 196-d', 'https://dol.ny.gov/system/files/documents/2025/01/tips-and-gratuities-frequently-asked-questions.pdf', '2026-10-27', null, 'pending attorney review', 'published'),
  ('ny-card_fees', 'NY', 'card_fees', 'depends', 'Your employer may subtract only your pro-rated share of the card company''s fee from a card tip, and must pay card tips by the next regular payday.', 'New York Labor Law section 196-d; Hospitality Industry Wage Order (12 NYCRR Part 146)', 'https://dol.ny.gov/system/files/documents/2025/01/tips-and-gratuities-frequently-asked-questions.pdf', '2026-10-27', null, 'pending attorney review', 'published'),
  ('fl-meal_break', 'FL', 'meal_break', 'no', 'No. Florida has no meal break law for adults, and federal law doesn''t require one either. If you get a meal break of about 30 minutes or more and you''re completely relieved of duty, it can be unpaid.', 'No Florida statute for adults (US DOL table of state meal period laws); Fair Labor Standards Act', 'https://www.dol.gov/agencies/whd/state/meal-breaks', '2026-10-27', null, 'pending attorney review', 'published'),
  ('fl-rest_break', 'FL', 'rest_break', 'no', 'No. Florida doesn''t require paid rest breaks for adults, and federal law doesn''t either. If your employer gives short breaks, federal law says they must be paid.', 'No Florida statute (US DOL table of state rest period laws); Fair Labor Standards Act', 'https://www.dol.gov/agencies/whd/state/rest-periods', '2026-10-27', null, 'pending attorney review', 'published'),
  ('fl-tip_credit', 'FL', 'tip_credit', 'yes', 'Yes. Since September 30, 2026, Florida''s minimum wage is $15.00 an hour, and tipped employees must get a cash wage of at least $11.98 an hour; up to $3.02 an hour of tips can count toward the minimum. These rates run through December 31, 2027.', 'Florida Constitution, Article X, Section 24; Florida Minimum Wage Act (section 448.110, Florida Statutes)', 'https://www.floridajobs.org/docs/business-growth-and-partnerships/for-employers/posters-and-required-notices/2026-minimum-wage/2026-minimum-wage-announcement799fb962a1e242c0b4bce1b9a711d677.pdf', '2026-10-27', '2027-12-31', 'pending attorney review', 'published'),
  ('il-meal_break', 'IL', 'meal_break', 'depends', 'Only on longer shifts. If you work 7½ hours, you''re owed a meal period of at least 20 minutes, starting no later than 5 hours into the shift, and another 20 minutes for every additional 4½ continuous hours. If you have to work through it, it must be paid. Shorter shifts aren''t covered.', 'One Day Rest in Seven Act, 820 ILCS 140', 'https://labor.illinois.gov/laws-rules/fls/odrisa.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('il-rest_break', 'IL', 'rest_break', 'depends', 'Employers must allow reasonable bathroom breaks. The US Department of Labor also lists a paid rest break rule that applies only to certain workplaces in Cook County. Whether that one covers you depends on your workplace; the Illinois Department of Labor can tell you.', 'One Day Rest in Seven Act, 820 ILCS 140 (US DOL table of state rest period laws)', 'https://www.dol.gov/agencies/whd/state/rest-periods', '2026-10-27', null, 'pending attorney review', 'published'),
  ('il-tip_credit', 'IL', 'tip_credit', 'yes', 'Yes. Illinois'' minimum wage is $15.00 an hour, and your employer can count tips for up to 40% of it, so your cash wage must be at least $9.00 an hour. If your tips plus wages come to less than $15.00, your employer must make up the difference. Chicago and some other places set higher minimums.', 'Illinois Minimum Wage Law, 820 ILCS 105', 'https://labor.illinois.gov/faqs/minimum-wage-overtime-faq.html', '2026-10-27', null, 'pending attorney review', 'published'),
  ('il-manager_tips', 'IL', 'manager_tips', 'no', 'No. In Illinois, tips are the property of the employees who earned them and your employer can''t keep them. Tips must be paid within 13 days after the end of the pay period they were earned in. Federal law also bars managers and supervisors from taking your tips.', 'Illinois Wage Payment and Collection Act, 820 ILCS 115; Fair Labor Standards Act, 29 U.S.C. 203(m)(2)(B)', 'https://labor.illinois.gov/news/press-release.21141.html', '2026-10-27', null, 'pending attorney review', 'published')
